import unittest

from math_check import clamp


class ClampContractTests(unittest.TestCase):
    """Verify the exact frozen upstream behavior of ``clamp``."""

    def test_within_range_returns_value(self):
        self.assertEqual(clamp(5, 0, 10), 5)

    def test_below_low_returns_low(self):
        self.assertEqual(clamp(-1, 0, 10), 0)

    def test_above_high_returns_high(self):
        self.assertEqual(clamp(11, 0, 10), 10)

    def test_equal_to_low_returns_low(self):
        self.assertEqual(clamp(0, 0, 10), 0)

    def test_equal_to_high_returns_high(self):
        self.assertEqual(clamp(10, 0, 10), 10)

    def test_inverted_range_first_match_returns_low(self):
        self.assertEqual(clamp(5, 10, 0), 10)


if __name__ == "__main__":
    unittest.main()"}}
