.menu-filters {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
}

.category-btn {
  padding: 0.5rem 1.25rem;
  border-radius: 999px;
  border: 2px solid var(--border);
  background: var(--bg-card);
  color: var(--text-secondary);
