}

.card-img {
  font-size: 2.5rem;
  margin-bottom: 0.25rem;
}

.card-title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text);
}

.card-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
  flex: 1;
}

.card-price {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--accent);
  margin-top: auto;
}

/* ===================================================
   RESERVATION SECTION
   =================================================== */
#reservation {
  padding: 5rem 1rem;
  background: var(--bg-secondary);
  text-align: center;
}

.reservation-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
}

/* ===================================================
   MODAL OVERLAY — focus trap styles + z-index
   =================================================== */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  background: rgba(10, 5, 0, 0.6);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  animation: fadeInOverlay 0.2s ease;
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  overflow-y: auto;
}

/* hidden state */
.modal-overlay[hidden] {
