  cursor: pointer;
  line-height: 1;
}

.modal-close:hover,
.modal-close:focus-visible {
  background: var(--accent);
  color: #fff;
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.modal-desc {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

/* ===================================================
   RESERVATION FORM
   =================================================== */
.reservation-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.form-group label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-secondary);
}

.form-group input,
.form-group select {
  padding: 0.65rem 0.875rem;
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  background: var(--bg);
