{"name": "repository.write", "arguments": {"path": "cafe/app.js", "content": "/**
 * Artisan Brew Co. — app.js
 * Vanilla JS only — no frameworks, no build step.
 * Entry: DOMContentLoaded
 */

/* =====================================================
   (a) ENTRY POINT
   ===================================================== */
document.addEventListener('DOMContentLoaded', function () {
  initThemeToggle();
  initDrawerNav();
  initMenuFilter();
  initReservationModal();
  initHeroCTA();
});

/* =====================================================
   (b) THEME TOGGLE
   Toggles `dark-roast` class on body,
   persists preference to localStorage.
   ===================================================== */
function initThemeToggle() {
  var themeToggle = document.getElementById('theme-toggle');
  var themeIcon   = document.getElementById('theme-icon');

  if (!themeToggle) return;

  // Restore saved preference
  var saved = localStorage.getItem('cafe-theme');
  if (saved === 'dark') {
    document.body.classList.add('dark-roast');
    if (themeIcon) themeIcon.textContent = '☀️';
    themeToggle.setAttribute('aria-label', 'Switch to light theme');
  }

  themeToggle.addEventListener('click', function () {
    var isDark = document.body.classList.toggle('dark-roast');
    if (themeIcon) {
      themeIcon.textContent = isDark ? '☀️' : '🌙';
    }
    themeToggle.setAttribute('aria-label', isDark ? 'Switch to light theme' : 'Toggle theme');
    localStorage.setItem('cafe-theme', isDark ? 'dark' : 'light');
  });
}

/* =====================================================
   (c) DRAWER NAV
   Toggles aria-expanded + .is-open CSS class.
   Closes on outside click or Escape.
   ===================================================== */
function initDrawerNav() {
  var toggle = document.getElementById('drawer-toggle');
  var nav    = document.getElementById('drawer-nav');

  if (!toggle || !nav) return;

  function openDrawer() {
    nav.classList.add('is-open');
    toggle.setAttribute('aria-expanded', 'true');
    toggle.setAttribute('aria-label', 'Close navigation menu');
  }

  function closeDrawer() {
    nav.classList.remove('is-open');
    toggle.setAttribute('aria-expanded', 'false');
    toggle.setAttribute('aria-label', 'Open navigation menu');
  }

  function isDrawerOpen() {
    return nav.classList.contains('is-open');
  }

  toggle.addEventListener('click', function (e) {
    e.stopPropagation();
    if (isDrawerOpen()) {
      closeDrawer();
    } else {
      openDrawer();
    }
  });

  // Close on outside click
  document.addEventListener('click', function (e) {
    if (isDrawerOpen() && !nav.contains(e.target) && e.target !== toggle) {
      closeDrawer();
    }
  });

  // Close on Escape
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && isDrawerOpen()) {
      closeDrawer();
      toggle.focus();
    }
  });

  // Close drawer after nav link click (mobile UX)
  var navLinks = nav.querySelectorAll('a');
  navLinks.forEach(function (link) {
    link.addEventListener('click', function () {
      closeDrawer();
    });
  });
}

/* =====================================================
   (d) MENU FILTER
   Category buttons add .active + show/hide cards
   by matching data-category attribute.
   ===================================================== */
function initMenuFilter() {
  var filterButtons = document.querySelectorAll('.category-btn[data-filter]');
  var menuCards     = document.querySelectorAll('.menu-card[data-category]');

  if (!filterButtons.length) return;

  filterButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var filter = btn.getAttribute('data-filter');

      // Update button active state + aria-pressed
      filterButtons.forEach(function (b) {
        b.classList.remove('active');
        b.setAttribute('aria-pressed', 'false');
      });
      btn.classList.add('active');
      btn.setAttribute('aria-pressed', 'true');

      // Show / hide cards
      menuCards.forEach(function (card) {
        var category = card.getAttribute('data-category');
        if (filter === 'all' || filter === category) {
          card.classList.remove('hidden');
        } else {
          card.classList.add('hidden');
        }
      });
    });
  });
}

/* =====================================================
   (e) RESERVATION MODAL
   Open / Close, focus trap, Escape dismiss,
   form validation with inline error messages.
   ===================================================== */
function initReservationModal() {
  var modal         = document.getElementById('reservation-modal');
  var openBtn       = document.getElementById('open-reservation-modal');
  var closeBtn      = document.getElementById('close-modal');
  var cancelBtn     = document.getElementById('cancel-reservation');
  var form          = document.getElementById('reservation-form');
  var successMsg    = document.getElementById('form-success');

  if (!modal) return;

  // ----- Open -----
  function openModal() {
    modal.removeAttribute('hidden');
    modal.removeAttribute('style');
    document.body.style.overflow = 'hidden';

    // Focus first focusable element inside modal
    var firstFocusable = getModalFocusables()[0];
    if (firstFocusable) {
      firstFocusable.focus();
    } else {
      modal.focus();
    }
  }

  // ----- Close -----
  function closeModal() {
    modal.setAttribute('hidden', '');
    document.body.style.overflow = '';
    clearFormErrors();
    if (successMsg) successMsg.setAttribute('hidden', '');
    // Return focus to opener
    if (openBtn) openBtn.focus();
  }

  if (openBtn) {
    openBtn.addEventListener('click', openModal);
  }

  if (closeBtn) {
    closeBtn.addEventListener('click', closeModal);
  }

  if (cancelBtn) {
    cancelBtn.addEventListener('click', closeModal);
  }

  // Close on overlay backdrop click
  modal.addEventListener('click', function (e) {
    if (e.target === modal) {
      closeModal();
    }
  });

  // Escape key dismissal
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !modal.hasAttribute('hidden')) {
      closeModal();
    }
  });

  // ----- Focus Trap -----
  modal.addEventListener('keydown', function (e) {
    if (e.key !== 'Tab') return;

    var focusables = getModalFocusables();
    if (focusables.length === 0) return;

    var first = focusables[0];
    var last  = focusables[focusables.length - 1];

    if (e.shiftKey) {
      // Shift+Tab: if on first, wrap to last
      if (document.activeElement === first) {
        e.preventDefault();
        last.focus();
      }
    } else {
      // Tab: if on last, wrap to first
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  });

  function getModalFocusables() {
    var container = modal.querySelector('.modal-container') || modal;
    return Array.from(
      container.querySelectorAll(
        'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
      )
    );
  }

  // ----- Form Validation -----
  if (form) {
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      clearFormErrors();
      var valid = validateReservationForm();
      if (valid) {
        showFormSuccess();
      }
    });
  }

  function validateReservationForm() {
    var isValid = true;

    // Name — non-empty
    var nameInput = document.getElementById('guest-name');
    var nameError = document.getElementById('name-error');
    if (nameInput && nameError) {
      var nameVal = nameInput.value.trim();
      if (!nameVal) {
        setFieldError(nameInput, nameError, 'Please enter your full name.');
        isValid = false;
      }
    }

    // Party size — must be 1–10
    var sizeInput = document.getElementById('party-size');
    var sizeError = document.getElementById('party-size-error');
    if (sizeInput && sizeError) {
      var sizeVal = parseInt(sizeInput.value, 10);
      if (!sizeInput.value || isNaN(sizeVal) || sizeVal < 1 || sizeVal > 10) {
        setFieldError(sizeInput, sizeError, 'Please select a party size between 1 and 10.');
        isValid = false;
      }
    }

    // Date — required, not in past
    var dateInput = document.getElementById('reservation-date');
    var dateError = document.getElementById('date-error');
    if (dateInput && dateError) {
      var dateVal = dateInput.value;
      if (!dateVal) {
        setFieldError(dateInput, dateError, 'Please select a date.');
        isValid = false;
      } else {
        var today = new Date();
        today.setHours(0, 0, 0, 0);
        var chosen = new Date(dateVal + 'T00:00:00');
        if (chosen < today) {
          setFieldError(dateInput, dateError, 'Please select a date that is not in the past.');
          isValid = false;
        }
      }
    }

    // Time — required
    var timeInput = document.getElementById('reservation-time');
    var timeError = document.getElementById('time-error');
    if (timeInput && timeError) {
      var timeVal = timeInput.value;
      if (!timeVal) {
        setFieldError(timeInput, timeError, 'Please select a time.');
        isValid = false;
      }
    }

    return isValid;
  }

  function setFieldError(input, errorEl, message) {
    input.classList.add('input-error');
    errorEl.textContent = message;
    input.setAttribute('aria-invalid', 'true');
  }

  function clearFormErrors() {
    var inputs = form ? form.querySelectorAll('input, select') : [];
    inputs.forEach(function (el) {
      el.classList.remove('input-error');
      el.removeAttribute('aria-invalid');
    });
    var errors = form ? form.querySelectorAll('.field-error') : [];
    errors.forEach(function (el) {
      el.textContent = '';
    });
  }

  function showFormSuccess() {
    if (form) form.reset();
    clearFormErrors();
    if (successMsg) {
      successMsg.removeAttribute('hidden');
      successMsg.focus();
    }
    // Auto-close modal after 2.5 seconds
    setTimeout(function () {
      closeModal();
    }, 2500);
  }
}

/* =====================================================
   (f) HERO CTA — smooth scroll to #menu / #reservation
   ===================================================== */
function initHeroCTA() {
  var ctaButtons = document.querySelectorAll('[data-scroll-target]');

  ctaButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var targetId = btn.getAttribute('data-scroll-target');
      var targetEl = document.getElementById(targetId);
      if (targetEl) {
        targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });
}
