   Artisan Cafe — Stylesheet
   ============================================================ */

/* ── CSS Custom Properties (Light Theme) ────────────────── */
:root {
  --bg: #faf7f2;
  --bg-secondary: #f0ebe0;
  --text: #2c1a0e;
  --text-secondary: #5c4a35;
  --accent: #c0622f;
  --accent-hover: #a0501f;
  --accent-light: #f5dfd0;
  --border: #d4c4b0;
  --shadow: rgba(44, 26, 14, 0.12);
  --modal-overlay: rgba(44, 26, 14, 0.65);
  --radius: 0.5rem;
  --transition: 0.25s ease;
  --font-sans: 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-serif: Georgia, 'Times New Roman', serif;
  --nav-height: 64px;
}

/* ── Dark Roast Theme ────────────────────────────────────── */
body.dark-roast {
  --bg: #1a1008;
  --bg-secondary: #2a1c10;
  --text: #f5ede0;
  --text-secondary: #c8b49a;
  --accent: #e8845a;
  --accent-hover: #f09a6e;
  --accent-light: #3a2010;
  --border: #4a3020;
  --shadow: rgba(0, 0, 0, 0.4);
  --modal-overlay: rgba(0, 0, 0, 0.8);
}

/* ── Reset & Base ────────────────────────────────────────── */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-sans);
  background-color: var(--bg);
  color: var(--text);
  line-height: 1.6;
  transition: background-color var(--transition), color var(--transition);
}

img,
svg {
  max-width: 100%;
  display: block;
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover,
a:focus {
  color: var(--accent-hover);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

ul {
  list-style: none;
}

/* ── Typography ─────────────────────────────────────────── */
h1, h2, h3 {
  font-family: var(--font-serif);
  line-height: 1.25;
  color: var(--text);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.25rem); }
h3 { font-size: 1.125rem; }

/* ── Utility ─────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.65rem 1.5rem;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  border: 2px solid transparent;
  transition: background-color var(--transition), color var(--transition),
              border-color var(--transition), transform 0.15s ease,
              box-shadow var(--transition);
  text-decoration: none;
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.btn-primary {
  background-color: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.btn-primary:hover,
.btn-primary:focus {
  background-color: var(--accent-hover);
  border-color: var(--accent-hover);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px var(--shadow);
  color: #fff;
}

.btn-secondary {
  background-color: transparent;
  color: var(--accent);
  border-color: var(--accent);
}

.btn-secondary:hover,
.btn-secondary:focus {
  background-color: var(--accent-light);
  color: var(--accent-hover);
}

.hidden {
  display: none !important;
}

/* ── Header ─────────────────────────────────────────────── */
header {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: var(--bg);
  border-bottom: 1px solid var(--border);
  box-shadow: 0 2px 8px var(--shadow);
  height: var(--nav-height);
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 0.4rem;
  text-decoration: none;
  flex-shrink: 0;
}

.logo:hover,
.logo:focus {
  color: var(--accent);
  outline: none;
}

nav#drawer-nav {
  margin-left: auto;
}

nav#drawer-nav ul {
  display: flex;
  gap: 1.5rem;
  align-items: center;
}

nav#drawer-nav a {
  color: var(--text);
  font-weight: 500;
  padding: 0.25rem 0;
  border-bottom: 2px solid transparent;
  text-decoration: none;
  transition: color var(--transition), border-color var(--transition);
}

nav#drawer-nav a:hover,
nav#drawer-nav a:focus {
  color: var(--accent);
  border-bottom-color: var(--accent);
  outline: none;
}

/* Theme toggle button */
#theme-toggle {
  background: none;
  border: 2px solid var(--border);
  border-radius: 50%;
  width: 40px;
  height: 40px;
  font-size: 1.2rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), background-color var(--transition),
              transform var(--transition);
  flex-shrink: 0;
  color: var(--text);
}

#theme-toggle:hover,
#theme-toggle:focus-visible {
  border-color: var(--accent);
  background-color: var(--accent-light);
  transform: rotate(20deg);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* Nav toggle (hamburger) — hidden on desktop */
.nav-toggle {
  display: none;
  background: none;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  padding: 0.4rem 0.6rem;
  cursor: pointer;
  color: var(--text);
  font-size: 1.4rem;
  line-height: 1;
  margin-left: auto;
  transition: border-color var(--transition), background-color var(--transition);
}

.nav-toggle:hover,
.nav-toggle:focus-visible {
  border-color: var(--accent);
  background-color: var(--accent-light);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.hamburger::before {
  content: '☰';
}

/* ── Hero Section ───────────────────────────────────────── */
#hero {
  min-height: calc(100vh - var(--nav-height));
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 4rem 1.5rem;
  background: linear-gradient(135deg, var(--bg) 0%, var(--bg-secondary) 100%);
  position: relative;
  overflow: hidden;
}

#hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, var(--accent-light) 0%, transparent 70%);
  opacity: 0.4;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 720px;
}

.hero-content h1 {
  margin-bottom: 1rem;
}

.hero-subtitle {
  font-size: 1.15rem;
  color: var(--text-secondary);
  margin-bottom: 2rem;
  max-width: 540px;
  margin-left: auto;
  margin-right: auto;
}

.hero-cta {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

/* CTA animations */
@keyframes pulse-cta {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(192, 98, 47, 0.5);
    transform: translateY(0);
  }
  50% {
    box-shadow: 0 0 0 10px rgba(192, 98, 47, 0);
    transform: translateY(-3px);
  }
}

@keyframes float-cta {
  0%, 100% { transform: translateY(0); }
  50%       { transform: translateY(-6px); }
}

.cta-pulse {
  animation: pulse-cta 2.4s ease-in-out infinite;
}

.cta-float {
  animation: float-cta 3s ease-in-out infinite;
}

/* ── Menu Section ───────────────────────────────────────── */
#menu {
  padding: 5rem 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
}

#menu h2 {
  text-align: center;
  margin-bottom: 2rem;
}

/* Category filter buttons */
.category-filters {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
}

.category-btn {
  padding: 0.45rem 1.25rem;
  border-radius: 2rem;
  border: 2px solid var(--border);
  background-color: var(--bg);
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color var(--transition), color var(--transition),
              border-color var(--transition), transform 0.15s ease;
  text-transform: capitalize;
}

.category-btn:hover,
.category-btn:focus-visible {
  border-color: var(--accent);
  color: var(--accent);
  transform: translateY(-1px);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.category-btn.active {
  background-color: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

/* Menu grid */
.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.menu-card {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) * 2);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  transition: box-shadow var(--transition), transform var(--transition);
}

.menu-card:hover {
  box-shadow: 0 8px 24px var(--shadow);
  transform: translateY(-4px);
}

.menu-card-img {
  font-size: 2.5rem;
  text-align: center;
  margin-bottom: 0.5rem;
}

.menu-card-title {
  font-family: var(--font-serif);
  font-size: 1.05rem;
}

.menu-card-desc {
  font-size: 0.875rem;
  color: var(--text-secondary);
  flex: 1;
}

.menu-card-price {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--accent);
  margin-top: 0.5rem;
}

/* ── Reservation CTA Section ────────────────────────────── */
#reservation {
  padding: 5rem 1.5rem;
  text-align: center;
  background-color: var(--bg-secondary);
  border-top: 1px solid var(--border);
}

#reservation h2 {
  margin-bottom: 0.75rem;
}

#reservation p {
  color: var(--text-secondary);
  margin-bottom: 2rem;
  font-size: 1.05rem;
}

/* ── Modal ───────────────────────────────────────────────── */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 500;
  background-color: var(--modal-overlay);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  /* shown/hidden via JS removing/adding [hidden] */
}

.modal-overlay[hidden] {
  display: none;
}

.modal-container {
  background-color: var(--bg);
  border-radius: calc(var(--radius) * 2);
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 520px;
  position: relative;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  max-height: 90vh;
  overflow-y: auto;
}

.modal-close {
  position: absolute;
  top: 1rem;
  right: 1rem;
  background: none;
  border: 2px solid var(--border);
  border-radius: 50%;
  width: 36px;
  height: 36px;
  font-size: 1.25rem;
  line-height: 1;
  cursor: pointer;
  color: var(--text-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color var(--transition), color var(--transition),
              background-color var(--transition);
}

.modal-close:hover,
.modal-close:focus-visible {
  border-color: var(--accent);
  color: var(--accent);
  background-color: var(--accent-light);
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.modal-container h2 {
  margin-bottom: 0.5rem;
  padding-right: 2.5rem;
}

.modal-container > p {
  color: var(--text-secondary);
  margin-bottom: 1.75rem;
  font-size: 0.95rem;
}

/* ── Form ────────────────────────────────────────────────── */
.form-group {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 1.25rem;
}

label {
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--text);
}

input[type="text"],
input[type="date"],
input[type="time"],
select {
  padding: 0.6rem 0.85rem;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background-color: var(--bg);
  color: var(--text);
  font-size: 1rem;
  font-family: inherit;
  width: 100%;
  transition: border-color var(--transition), box-shadow var(--transition);
  appearance: auto;
}

input:focus,
select:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(192, 98, 47, 0.2);
}

input.invalid,
select.invalid {
  border-color: #d32f2f;
  box-shadow: 0 0 0 3px rgba(211, 47, 47, 0.2);
}

.field-error {
  font-size: 0.8rem;
  color: #d32f2f;
  min-height: 1rem;
  display: block;
}

.form-actions {
  display: flex;
  gap: 0.75rem;
  justify-content: flex-end;
  flex-wrap: wrap;
  margin-top: 1.5rem;
}

/* ── Footer ─────────────────────────────────────────────── */
footer {
  background-color: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 2.5rem 1.5rem;
  text-align: center;
}

.footer-inner {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  align-items: center;
}

.footer-brand {
  font-family: var(--font-serif);
  font-size: 1.3rem;
  font-weight: 700;
}

.footer-tagline {
  color: var(--text-secondary);
  font-size: 0.9rem;
}

.footer-nav {
  display: flex;
  gap: 1.5rem;
}

.footer-nav a {
  color: var(--text-secondary);
  font-size: 0.9rem;
  font-weight: 500;
  transition: color var(--transition);
}

.footer-nav a:hover,
.footer-nav a:focus {
  color: var(--accent);
}

.footer-copy {
  color: var(--text-secondary);
  font-size: 0.8rem;
  margin-top: 0.5rem;
}

/* ── Responsive — Mobile (max-width: 768px) ─────────────── */
@media (max-width: 768px) {
  :root {
    --nav-height: 56px;
  }

  .nav-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    order: 2;
  }

  #theme-toggle {
    order: 3;
    margin-left: 0;
  }

  nav#drawer-nav {
    position: fixed;
    top: var(--nav-height);
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--bg);
    z-index: 200;
    transform: translateX(-100%);
    transition: transform 0.3s ease;
    padding: 2rem 1.5rem;
    border-right: 1px solid var(--border);
    width: 75%;
    max-width: 300px;
    overflow-y: auto;
    order: 4;
    margin-left: 0;
  }

  nav#drawer-nav.open {
    transform: translateX(0);
    box-shadow: 4px 0 20px var(--shadow);
  }

  nav#drawer-nav ul {
    flex-direction: column;
    gap: 1rem;
    align-items: flex-start;
  }

  nav#drawer-nav a {
    font-size: 1.1rem;
    padding: 0.5rem 0;
  }

  .logo {
    flex: 1;
    order: 1;
  }

  /* Menu grid collapses to 1 column */
  .menu-grid {
    grid-template-columns: 1fr;
  }

  /* Hero CTA buttons stack */
  .hero-cta {
    flex-direction: column;
    align-items: center;
  }

  .hero-cta .btn {
    width: 100%;
    max-width: 320px;
  }

  /* Form actions stack */
  .form-actions {
    flex-direction: column;
  }

  .form-actions .btn {
    width: 100%;
  }

  /* Modal takes full width */
  .modal-container {
    padding: 2rem 1.25rem;
    margin: 0;
    max-width: 100%;
    max-height: 85vh;
  }
}

/* ── Responsive — Tablet (769px–1024px) ─────────────────── */
@media (min-width: 769px) and (max-width: 1024px) {
  .menu-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* ── Reduced Motion ─────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
