{"name": "repository.write", "arguments": {"path": "cafe/app.js", "content": "/**
 * Artisan Cafe — app.js
 * Vanilla JS, no framework, no build step.
 */

'use strict';

document.addEventListener('DOMContentLoaded', () => {

  /* ── Theme Toggle ─────────────────────────────────────── */
  const themeToggle = document.getElementById('theme-toggle');
  const DARK_CLASS  = 'dark-roast';
  const STORAGE_KEY = 'cafe-theme';

  function applyTheme(dark) {
    document.body.classList.toggle(DARK_CLASS, dark);
    themeToggle.textContent = dark ? '☀️' : '🌙';
    themeToggle.setAttribute('aria-label', dark ? 'Switch to light theme' : 'Switch to dark theme');
  }

  // Restore persisted theme
  const savedDark = localStorage.getItem(STORAGE_KEY) === 'dark';
  applyTheme(savedDark);

  themeToggle.addEventListener('click', () => {
    const isDark = document.body.classList.contains(DARK_CLASS);
    applyTheme(!isDark);
    localStorage.setItem(STORAGE_KEY, !isDark ? 'dark' : 'light');
  });


  /* ── Mobile Drawer Nav ────────────────────────────────── */
  const navToggle = document.querySelector('.nav-toggle');
  const drawerNav = document.getElementById('drawer-nav');

  function setDrawer(open) {
    navToggle.setAttribute('aria-expanded', String(open));
    drawerNav.classList.toggle('open', open);
  }

  navToggle.addEventListener('click', () => {
    const isOpen = navToggle.getAttribute('aria-expanded') === 'true';
    setDrawer(!isOpen);
  });

  // Close on outside click
  document.addEventListener('click', (e) => {
    if (!drawerNav.contains(e.target) && e.target !== navToggle) {
      setDrawer(false);
    }
  });

  // Close nav on link click (mobile UX)
  drawerNav.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', () => setDrawer(false));
  });


  /* ── Menu Category Filter ─────────────────────────────── */
  const categoryBtns = document.querySelectorAll('.category-btn');
  const menuCards    = document.querySelectorAll('.menu-card');

  categoryBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      const filter = btn.dataset.filter;

      // Update active state
      categoryBtns.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');

      // Show/hide cards
      menuCards.forEach(card => {
        const match = filter === 'all' || card.dataset.category === filter;
        card.classList.toggle('hidden', !match);
      });
    });
  });


  /* ── Reservation Modal ────────────────────────────────── */
  const modal           = document.getElementById('reservation-modal');
  const openModalBtn    = document.getElementById('open-reservation');
  const closeModalBtn   = document.getElementById('modal-close');
  const cancelModalBtn  = document.getElementById('cancel-reservation');
  const reservationForm = document.getElementById('reservation-form');

  // Focus trap helpers
  const FOCUSABLE_SELECTORS = [
    'a[href]', 'button:not([disabled])', 'input:not([disabled])',
    'select:not([disabled])', 'textarea:not([disabled])', '[tabindex]:not([tabindex="-1"])'
  ].join(', ');

  function getFocusableElements() {
    return Array.from(modal.querySelectorAll(FOCUSABLE_SELECTORS));
  }

  function openModal() {
    modal.removeAttribute('hidden');
    document.body.style.overflow = 'hidden';
    const focusable = getFocusableElements();
    if (focusable.length) focusable[0].focus();
  }

  function closeModal() {
    modal.setAttribute('hidden', '');
    document.body.style.overflow = '';
    openModalBtn.focus();
    clearFormErrors();
    reservationForm.reset();
  }

  openModalBtn.addEventListener('click', openModal);
  closeModalBtn.addEventListener('click', closeModal);
  cancelModalBtn.addEventListener('click', closeModal);

  // Close on overlay click
  modal.addEventListener('click', (e) => {
    if (e.target === modal) closeModal();
  });

  // Escape key
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !modal.hasAttribute('hidden')) closeModal();
  });

  // Focus trap — Tab / Shift+Tab cycling
  modal.addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;
    const focusable = getFocusableElements();
    if (!focusable.length) return;

    const first = focusable[0];
    const last  = focusable[focusable.length - 1];

    if (e.shiftKey) {
      if (document.activeElement === first) {
        e.preventDefault();
        last.focus();
      }
    } else {
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  });


  /* ── Form Validation ──────────────────────────────────── */
  function clearFormErrors() {
    reservationForm.querySelectorAll('.field-error').forEach(el => el.textContent = '');
    reservationForm.querySelectorAll('.invalid').forEach(el => el.classList.remove('invalid'));
  }

  function setError(input, errorId, message) {
    const errEl = document.getElementById(errorId);
    if (errEl) errEl.textContent = message;
    input.classList.add('invalid');
    input.setAttribute('aria-describedby', errorId);
  }

  function validateForm() {
    clearFormErrors();
    let valid = true;

    const nameInput  = document.getElementById('guest-name');
    const partyInput = document.getElementById('party-size');
    const dateInput  = document.getElementById('reservation-date');
    const timeInput  = document.getElementById('reservation-time');

    if (!nameInput.value.trim()) {
      setError(nameInput, 'name-error', 'Please enter your name.');
      valid = false;
    }

    const partyVal = parseInt(partyInput.value, 10);
    if (!partyInput.value || isNaN(partyVal) || partyVal < 1 || partyVal > 10) {
      setError(partyInput, 'party-error', 'Please select a party size (1–10).');
      valid = false;
    }

    if (!dateInput.value) {
      setError(dateInput, 'date-error', 'Please pick a date.');
      valid = false;
    } else {
      const selected = new Date(dateInput.value);
      const today    = new Date();
      today.setHours(0, 0, 0, 0);
      if (selected < today) {
        setError(dateInput, 'date-error', 'Date cannot be in the past.');
        valid = false;
      }
    }

    if (!timeInput.value) {
      setError(timeInput, 'time-error', 'Please select a time.');
      valid = false;
    }

    return valid;
  }

  reservationForm.addEventListener('submit', (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    // Success — show confirmation, close modal
    alert(`Reservation confirmed! See you soon, ${document.getElementById('guest-name').value.trim()}! 🎉`);
    closeModal();
  });


  /* ── Hero CTA Smooth Scroll ───────────────────────────── */
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', (e) => {
      const target = document.querySelector(anchor.getAttribute('href'));
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    });
  });

});
"}}
