   Kobits Café — Main Stylesheet
   ========================================================= */

/* ----- Reset & Base ----- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg:        #fdf6f0;
  --color-surface:   #ffffff;
  --color-primary:   #6b3f2a;
  --color-primary-h: #8a5340;
  --color-accent:    #d4845a;
  --color-text:      #2c1a0e;
  --color-muted:     #7a6055;
  --color-border:    #e8d5c9;
  --color-success:   #2d8653;
  --color-overlay:   rgba(0, 0, 0, 0.45);
  --radius-sm:       6px;
  --radius-md:       12px;
  --radius-lg:       20px;
  --shadow-card:     0 2px 12px rgba(107, 63, 42, 0.10);
  --shadow-drawer:   -4px 0 24px rgba(0, 0, 0, 0.15);
  --transition:      0.25s ease;
  --font-main:       'Segoe UI', system-ui, -apple-system, sans-serif;
  --drawer-width:    360px;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-main);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  line-height: 1.6;
}

/* ----- HEADER ----- */
.site-header {
  background: var(--color-primary);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 100;
  box-shadow: 0 2px 8px rgba(0,0,0,0.18);
}

.header-inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

/* Cart toggle button */
.cart-btn {
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  padding: 8px 18px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
}

.cart-btn:hover,
.cart-btn:focus-visible {
  background: #bf7048;
  transform: scale(1.04);
  outline: 2px solid #fff;
}

/* ----- HERO ----- */
.hero {
  background: linear-gradient(135deg, #6b3f2a 0%, #c4714a 100%);
  color: #fff;
  text-align: center;
  padding: 64px 24px 48px;
}

.hero h2 {
  font-size: 2.2rem;
  font-weight: 800;
  margin-bottom: 12px;
}

.hero p {
  font-size: 1.1rem;
  opacity: 0.88;
}

/* ----- SECTION TITLES ----- */
.section-title {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 24px;
}

/* ----- MENU SECTION ----- */
.menu-section {
  max-width: 1100px;
  margin: 0 auto;
  padding: 56px 24px 40px;
}

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 24px;
}

/* ----- MENU CARD ----- */
.menu-card {
  background: var(--color-surface);
