# ---------------------------------------------------------------------------
# Helpers — minimal DOM inspector
# ---------------------------------------------------------------------------

class _DOMParser(HTMLParser):
    """Collects all tags, ids, classes, and data-attributes from an HTML doc."""

    def __init__(self):
        super().__init__()
        self.ids: set     = set()
        self.classes: set = set()
        self.tags: list   = []          # list of (tag, attrs_dict)
        self.data_attrs: dict = {}      # id -> data attrs

    def handle_starttag(self, tag, attrs):
        attr_dict = dict(attrs)
        self.tags.append((tag, attr_dict))

        if 'id' in attr_dict:
            self.ids.add(attr_dict['id'])
            # collect data-* on this element
            data = {k: v for k, v in attr_dict.items() if k.startswith('data-')}
            if data:
                self.data_attrs[attr_dict['id']] = data

        raw_cls = attr_dict.get('class', '')
        for cls in raw_cls.split():
            self.classes.add(cls)


def _parse_html(path: Path) -> _DOMParser:
    parser = _DOMParser()
    parser.feed(path.read_text(encoding='utf-8'))
    return parser


# ---------------------------------------------------------------------------
# Python mirrors of JS business logic
# ---------------------------------------------------------------------------

TAX_RATE = 0.08

BREW_METHODS = {
    'pour_over':    {'label': 'Pour Over',    'ratio': 16, 'brew_time': '3 \u2013 4 min'},
    'french_press': {'label': 'French Press', 'ratio': 12, 'brew_time': '4 min (+ 30 s press)'},
    'espresso':     {'label': 'Espresso',     'ratio': 2,  'brew_time': '25 \u2013 30 s'},
}


def calculate_brew(method_key: str, bean_weight: float) -> dict:
    """Python mirror of the JS calculateBrewRatio() function."""
    if method_key not in BREW_METHODS or bean_weight <= 0:
        raise ValueError(f'Invalid method or weight: {method_key!r}, {bean_weight}')
    method   = BREW_METHODS[method_key]
    water_ml = round(bean_weight * method['ratio'])
    return {
        'label':     method['label'],
        'beans':     bean_weight,
        'water_ml':  water_ml,
        'brew_time': method['brew_time'],
        'ratio':     f"1 : {method['ratio']}",
    }


def calculate_cart_totals(items: list) -> dict:
    """
    Python mirror of the JS updateTotals() logic.
    items: list of dicts with keys 'price' (float) and 'qty' (int).
    """
    subtotal = sum(item['price'] * item['qty'] for item in items)
    tax      = subtotal * TAX_RATE
    total    = subtotal + tax
    return {'subtotal': round(subtotal, 2), 'tax': round(tax, 2), 'total': round(total, 2)}


