        result = calculate_cart_totals(items)
        assert abs(result['tax'] - 0.28) < 0.01

    def test_single_item_total(self):
        items = [{'price': 3.50, 'qty': 1}]
        result = calculate_cart_totals(items)
        assert abs(result['total'] - 3.78) < 0.01

    def test_multiple_items_subtotal(self):
        items = [
            {'price': 3.50, 'qty': 2},   # Espresso x2 = 7.00
            {'price': 4.50, 'qty': 1},   # Flat White  = 4.50
        ]
        result = calculate_cart_totals(items)
        assert result['subtotal'] == 11.50

    def test_multiple_items_tax_rate(self):
        items = [{'price': 10.00, 'qty': 1}]
        result = calculate_cart_totals(items)
        assert abs(result['tax'] - 0.80) < 0.001

    def test_multiple_items_total(self):
        items = [
            {'price': 3.50, 'qty': 2},
            {'price': 4.50, 'qty': 1},
        ]
        result = calculate_cart_totals(items)
        # subtotal=11.50, tax=0.92, total=12.42
        assert abs(result['total'] - 12.42) < 0.01

    def test_empty_cart_subtotal_zero(self):
        result = calculate_cart_totals([])
        assert result['subtotal'] == 0.0

    def test_empty_cart_tax_zero(self):
        result = calculate_cart_totals([])
        assert result['tax'] == 0.0

    def test_empty_cart_total_zero(self):
        result = calculate_cart_totals([])
        assert result['total'] == 0.0

    def test_qty_two_doubles_line_total(self):
        items_x1 = [{'price': 5.00, 'qty': 1}]
        items_x2 = [{'price': 5.00, 'qty': 2}]
        r1 = calculate_cart_totals(items_x1)
        r2 = calculate_cart_totals(items_x2)
        assert abs(r2['subtotal'] - r1['subtotal'] * 2) < 0.001

    def test_tax_is_eight_percent_of_subtotal(self):
        items = [{'price': 7.25, 'qty': 3}]
        result = calculate_cart_totals(items)
        expected_tax = round(result['subtotal'] * TAX_RATE, 2)
        assert abs(result['tax'] - expected_tax) < 0.001

    def test_total_equals_subtotal_plus_tax(self):
        items = [{'price': 4.50, 'qty': 2}, {'price': 3.00, 'qty': 1}]
        result = calculate_cart_totals(items)
        assert abs(result['total'] - (result['subtotal'] + result['tax'])) < 0.001


