<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Virtual Keyboard</title>
  <style>
    /* ───────────────────────── Reset & Base ───────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --bg:            #1a1a2e;
      --surface:       #16213e;
      --key-bg:        #0f3460;
      --key-bg-light:  #1a4a7a;
      --key-fg:        #e0e0e0;
      --key-border:    #0d2a50;
      --key-shadow:    #0a1f3a;
      --accent:        #e94560;
      --accent-light:  #ff6b6b;
      --display-bg:    #0d1b2a;
      --display-fg:    #c8f5ff;
      --caret:         #e94560;
      --radius:        8px;
      --transition:    0.08s ease;
    }

    body {
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      background: var(--bg);
      font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
      color: var(--key-fg);
      gap: 28px;
      padding: 24px 16px;
    }

    /* ───────────────────────── Header ───────────────────────── */
    header {
      text-align: center;
    }
    header h1 {
      font-size: clamp(1.4rem, 4vw, 2rem);
      font-weight: 700;
      letter-spacing: 0.06em;
      color: var(--accent-light);
    }
    header p {
      font-size: 0.8rem;
      opacity: 0.55;
      margin-top: 4px;
    }

    /* ───────────────────────── Display ───────────────────────── */
    .display-wrapper {
      width: 100%;
      max-width: 860px;
      background: var(--display-bg);
      border: 1.5px solid var(--key-border);
      border-radius: var(--radius);
      padding: 12px 16px;
      box-shadow: 0 4px 24px rgba(0,0,0,0.5);
      position: relative;
    }

    .display-label {
      font-size: 0.65rem;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      opacity: 0.4;
      margin-bottom: 6px;
    }

    #display {
      min-height: 52px;
      max-height: 120px;
      overflow-y: auto;
      font-size: clamp(1rem, 2.5vw, 1.3rem);
      font-family: 'Courier New', Courier, monospace;
      color: var(--display-fg);
      word-break: break-all;
      white-space: pre-wrap;
      line-height: 1.5;
      outline: none;
    }

    /* blinking caret effect */
    #display::after {
      content: '';
      display: inline-block;
      width: 2px;
      height: 1.1em;
      background: var(--caret);
      vertical-align: text-bottom;
      margin-left: 2px;
      animation: blink 1s step-end infinite;
    }

    @keyframes blink {
      0%, 100% { opacity: 1; }
      50%       { opacity: 0; }
    }

    .display-actions {
      display: flex;
      gap: 8px;
      margin-top: 8px;
    }

    .display-actions button {
      font-size: 0.7rem;
      padding: 4px 12px;
      border: 1px solid var(--key-border);
      border-radius: 4px;
      background: var(--key-bg);
      color: var(--key-fg);
      cursor: pointer;
      transition: background var(--transition);
      letter-spacing: 0.05em;
    }
    .display-actions button:hover  { background: var(--key-bg-light); }
    .display-actions button:active { background: var(--accent); }

    /* word / char counter */
    .counter {
      position: absolute;
      bottom: 10px;
      right: 14px;
      font-size: 0.65rem;
      opacity: 0.35;
    }

    /* ───────────────────────── Keyboard ───────────────────────── */
    .keyboard {
      display: flex;
      flex-direction: column;
      gap: 8px;
      background: var(--surface);
      border: 1.5px solid var(--key-border);
      border-radius: 16px;
      padding: 18px 20px 22px;
      box-shadow: 0 8px 40px rgba(0,0,0,0.6);
      width: 100%;
      max-width: 860px;
      user-select: none;
    }

    .key-row {
      display: flex;
      justify-content: center;
      gap: 6px;
    }

    /* ───── Key base ───── */
    .key {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      min-width: 44px;
      height: 46px;
      padding: 0 6px;
      background: var(--key-bg);
      color: var(--key-fg);
      border: 1px solid var(--key-border);
      border-bottom: 3px solid var(--key-shadow);
      border-radius: var(--radius);
      cursor: pointer;
      font-size: 0.78rem;
      font-weight: 600;
      letter-spacing: 0.03em;
      transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
      position: relative;
      -webkit-tap-highlight-color: transparent;
      outline: none;
    }

    .key:hover  { background: var(--key-bg-light); box-shadow: 0 0 8px rgba(233,69,96,0.25); }

    .key:active,
    .key.pressed {
      background: var(--accent);
      border-bottom-width: 1px;
      transform: translateY(2px);
      box-shadow: none;
      color: #fff;
    }

    /* sub-label (shift character) */
    .key .sub {
      font-size: 0.55rem;
      font-weight: 400;
      opacity: 0.55;
      line-height: 1;
      margin-bottom: 2px;
    }
    .key .main {
      line-height: 1;
    }

    /* ───── Special key sizes ───── */
    .key-tab       { min-width: 72px; }
    .key-caps      { min-width: 80px; }
    .key-shift-l,
    .key-shift-r   { min-width: 96px; }
    .key-enter     { min-width: 88px; }
    .key-backspace { min-width: 88px; }
    .key-space     { min-width: 280px; flex-grow: 1; max-width: 360px; }
    .key-ctrl,
    .key-alt,
    .key-win,
    .key-fn        { min-width: 60px; }

    /* Caps-lock active indicator */
    .key-caps.caps-on::before {
      content: '';
      position: absolute;
      bottom: 6px;
      left: 50%;
      transform: translateX(-50%);
      width: 6px;
      height: 6px;
      border-radius: 50%;
      background: var(--accent-light);
      box-shadow: 0 0 6px var(--accent-light);
    }

    /* Num row icons */
    .key .icon { font-size: 0.9rem; }

    /* ───────────────────────── Responsive ───────────────────────── */
    @media (max-width: 680px) {
      .keyboard { padding: 12px 8px 16px; gap: 5px; }
      .key-row   { gap: 4px; }
      .key       { min-width: 30px; height: 40px; font-size: 0.68rem; border-radius: 6px; }
      .key-tab, .key-caps, .key-backspace, .key-enter { min-width: 56px; }
      .key-shift-l, .key-shift-r { min-width: 68px; }
      .key-space  { min-width: 140px; }
      .key-ctrl, .key-alt, .key-win, .key-fn { min-width: 44px; }
    }
  </style>
</head>
<body>

  <header>
    <h1>⌨️ Virtual Keyboard</h1>
    <p>Click keys or type on your physical keyboard</p>
  </header>

  <!-- ─────────── Display ─────────── -->
  <div class="display-wrapper" role="region" aria-label="Text display area">
    <div class="display-label">Output</div>
    <div id="display" aria-live="polite" aria-atomic="true"></div>
    <div class="display-actions">
      <button id="btn-copy"  aria-label="Copy text">📋 Copy</button>
      <button id="btn-clear" aria-label="Clear text">🗑 Clear</button>
    </div>
    <span class="counter" id="counter">0 chars · 0 words</span>
  </div>

  <!-- ─────────── Keyboard ─────────── -->
  <div class="keyboard" role="group" aria-label="Virtual keyboard">

    <!-- Row 0 – Function / Escape row -->
    <div class="key-row">
      <button class="key" data-key="Escape"    data-output="">Esc</button>
      <button class="key" data-key="F1"        data-output="">F1</button>
      <button class="key" data-key="F2"        data-output="">F2</button>
      <button class="key" data-key="F3"        data-output="">F3</button>
      <button class="key" data-key="F4"        data-output="">F4</button>
      <button class="key" data-key="F5"        data-output="">F5</button>
      <button class="key" data-key="F6"        data-output="">F6</button>
      <button class="key" data-key="F7"        data-output="">F7</button>
      <button class="key" data-key="F8"        data-output="">F8</button>
      <button class="key" data-key="F9"        data-output="">F9</button>
      <button class="key" data-key="F10"       data-output="">F10</button>
      <button class="key" data-key="F11"       data-output="">F11</button>
      <button class="key" data-key="F12"       data-output="">F12</button>
    </div>

    <!-- Row 1 – Number row -->
    <div class="key-row">
      <button class="key" data-key="`"  data-shift="~"   data-output="`"><span class="sub">~</span><span class="main">`</span></button>
      <button class="key" data-key="1"  data-shift="!"   data-output="1"><span class="sub">!</span><span class="main">1</span></button>
      <button class="key" data-key="2"  data-shift="@"   data-output="2"><span class="sub">@</span><span class="main">2</span></button>
      <button class="key" data-key="3"  data-shift="#"   data-output="3"><span class="sub">#</span><span class="main">3</span></button>
      <button class="key" data-key="4"  data-shift="$"   data-output="4"><span class="sub">$</span><span class="main">4</span></button>
      <button class="key" data-key="5"  data-shift="%"   data-output="5"><span class="sub">%</span><span class="main">5</span></button>
      <button class="key" data-key="6"  data-shift="^"   data-output="6"><span class="sub">^</span><span class="main">6</span></button>
      <button class="key" data-key="7"  data-shift="&amp;" data-output="7"><span class="sub">&amp;</span><span class="main">7</span></button>
      <button class="key" data-key="8"  data-shift="*"   data-output="8"><span class="sub">*</span><span class="main">8</span></button>
      <button class="key" data-key="9"  data-shift="("   data-output="9"><span class="sub">(</span><span class="main">9</span></button>
      <button class="key" data-key="0"  data-shift=")"   data-output="0"><span class="sub">)</span><span class="main">0</span></button>
      <button class="key" data-key="-"  data-shift="_"   data-output="-"><span class="sub">_</span><span class="main">-</span></button>
      <button class="key" data-key="="  data-shift="+"   data-output="="><span class="sub">+</span><span class="main">=</span></button>
      <button class="key key-backspace" data-key="Backspace" data-output="">⌫ Backspace</button>
    </div>

    <!-- Row 2 – QWERTY -->
    <div class="key-row">
      <button class="key key-tab"  data-key="Tab"    data-output="&#9;">Tab ⇥</button>
      <button class="key" data-key="q" data-output="q">Q</button>
      <button class="key" data-key="w" data-output="w">W</button>
      <button class="key" data-key="e" data-output="e">E</button>
      <button class="key" data-key="r" data-output="r">R</button>
      <button class="key" data-key="t" data-output="t">T</button>
      <button class="key" data-key="y" data-output="y">Y</button>
      <button class="key" data-key="u" data-output="u">U</button>
      <button class="key" data-key="i" data-output="i">I</button>
      <button class="key" data-key="o" data-output="o">O</button>
