  <script>
  (() => {
    'use strict';

    // ─── State ───
    let text      = '';
    let capsLock  = false;
    let shiftActive = false;

    // ─── DOM refs ───
    const display    = document.getElementById('display');
    const counter    = document.getElementById('counter');
    const btnCopy    = document.getElementById('btn-copy');
    const btnClear   = document.getElementById('btn-clear');
    const keyCaps    = document.getElementById('key-caps');
    const keyShiftL  = document.getElementById('key-shift-l');
    const keyShiftR  = document.getElementById('key-shift-r');

    // ─── Helpers ───
    function updateDisplay() {
      // Show text; the ::after CSS pseudo-element handles the caret
      display.textContent = text;
      display.scrollTop = display.scrollHeight;
      const chars = text.length;
      const words = text.trim() === '' ? 0 : text.trim().split(/\s+/).length;
      counter.textContent = `${chars} char${chars !== 1 ? 's' : ''} · ${words} word${words !== 1 ? 's' : ''}`;
    }

    function flashKey(keyEl) {
      if (!keyEl) return;
      keyEl.classList.add('pressed');
      setTimeout(() => keyEl.classList.remove('pressed'), 150);
    }

    function findKeyEl(physicalKey) {
      // physicalKey is e.key (e.g. 'a', 'Enter', 'Shift', etc.)
      const normalized = physicalKey === ' ' ? ' ' : physicalKey;
      return document.querySelector(`.key[data-key="${CSS.escape(normalized)}"]`)
          || document.querySelector(`.key[data-key="${CSS.escape(physicalKey.toLowerCase())}"]`);
    }

    function applyShiftCaps(char) {
      const isLetter = /^[a-z]$/i.test(char);
      if (isLetter) {
        const upper = capsLock !== shiftActive; // XOR: caps flips case; shift flips again
        return upper ? char.toUpperCase() : char.toLowerCase();
      }
      return char;
    }

    function processOutput(keyEl) {
      const rawOut = keyEl.getAttribute('data-output');
      const shift  = keyEl.getAttribute('data-shift');
      const key    = keyEl.getAttribute('data-key');

      // Special keys first
      if (key === 'Backspace') {
        text = text.slice(0, -1);
        updateDisplay();
        return;
      }
      if (key === 'CapsLock') {
        capsLock = !capsLock;
        keyCaps.classList.toggle('caps-on', capsLock);
        return;
      }
      if (key === 'ShiftLeft' || key === 'ShiftRight') {
        // Shift is handled on mousedown/mouseup separately; nothing to append
        return;
      }
      // Non-printing specials (F-keys, Ctrl, Alt, Meta, Escape, Fn)
      if (!rawOut && key !== ' ' && key !== 'Tab' && key !== 'Enter') return;

      // Determine the character to append
      let char;
      if (key === ' ')    { char = ' '; }
      else if (key === 'Tab')   { char = '\t'; }
      else if (key === 'Enter') { char = '\n'; }
      else {
        const base = shiftActive && shift ? shift : rawOut;
        char = /^[a-z]$/.test(key) ? applyShiftCaps(base || key) : base;
      }

      if (char !== undefined && char !== null) {
        text += char;
        updateDisplay();
      }
    }

    // ─── Virtual key click ───
    document.querySelector('.keyboard').addEventListener('mousedown', e => {
      const keyEl = e.target.closest('.key');
      if (!keyEl) return;
      e.preventDefault(); // prevent focus steal

      const key = keyEl.getAttribute('data-key');
      if (key === 'ShiftLeft' || key === 'ShiftRight') {
        shiftActive = true;
        keyShiftL.classList.add('pressed');
        keyShiftR.classList.add('pressed');
        return;
      }
      flashKey(keyEl);
      processOutput(keyEl);
    });

    document.querySelector('.keyboard').addEventListener('mouseup', e => {
      const key = e.target.closest('.key')?.getAttribute('data-key');
      if (key === 'ShiftLeft' || key === 'ShiftRight') {
        shiftActive = false;
        keyShiftL.classList.remove('pressed');
        keyShiftR.classList.remove('pressed');
      }
    });

    // Release shift if mouse leaves keyboard while held
    document.querySelector('.keyboard').addEventListener('mouseleave', () => {
      if (shiftActive) {
        shiftActive = false;
        keyShiftL.classList.remove('pressed');
        keyShiftR.classList.remove('pressed');
      }
    });

    // Touch support
    document.querySelector('.keyboard').addEventListener('touchstart', e => {
      const keyEl = e.target.closest('.key');
      if (!keyEl) return;
      e.preventDefault();
      const key = keyEl.getAttribute('data-key');
      if (key === 'ShiftLeft' || key === 'ShiftRight') {
        shiftActive = !shiftActive; // toggle on touch
        keyShiftL.classList.toggle('pressed', shiftActive);
        keyShiftR.classList.toggle('pressed', shiftActive);
        return;
      }
      flashKey(keyEl);
      processOutput(keyEl);
    }, { passive: false });

    // ─── Physical keyboard ───
    document.addEventListener('keydown', e => {
      // Let Ctrl+C, Ctrl+A etc. pass through natively
      if (e.ctrlKey || e.metaKey) return;

      if (e.key === 'Shift') {
        shiftActive = true;
        keyShiftL.classList.add('pressed');
        keyShiftR.classList.add('pressed');
        return;
      }
      if (e.key === 'CapsLock') {
        capsLock = !capsLock;
        keyCaps.classList.toggle('caps-on', capsLock);
        flashKey(keyCaps);
        return;
      }

      // Prevent default for keys that would move page focus (Tab, Space, arrows)
      if (['Tab', ' ', 'ArrowUp', 'ArrowDown'].includes(e.key)) e.preventDefault();

      const keyEl = findKeyEl(e.key);
      flashKey(keyEl);

      if (e.key === 'Backspace') { text = text.slice(0, -1); updateDisplay(); return; }
      if (e.key === 'Enter')     { text += '\n'; updateDisplay(); return; }
      if (e.key === 'Tab')       { text += '\t'; updateDisplay(); return; }

      // Printable characters (single char)
      if (e.key.length === 1) {
        text += e.key; // physical keyboard already accounts for shift/caps
        updateDisplay();
      }
    });

    document.addEventListener('keyup', e => {
      if (e.key === 'Shift') {
        shiftActive = false;
        keyShiftL.classList.remove('pressed');
        keyShiftR.classList.remove('pressed');
      }
    });

    // ─── Toolbar buttons ───
    btnClear.addEventListener('click', () => {
      text = '';
      updateDisplay();
    });

    btnCopy.addEventListener('click', async () => {
      if (!text) return;
      try {
        await navigator.clipboard.writeText(text);
        const orig = btnCopy.textContent;
        btnCopy.textContent = '✅ Copied!';
        setTimeout(() => { btnCopy.textContent = orig; }, 1500);
      } catch {
        // Fallback for older browsers / non-secure contexts
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.position = 'fixed';
        ta.style.opacity  = '0';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        btnCopy.textContent = '✅ Copied!';
        setTimeout(() => { btnCopy.textContent = '📋 Copy'; }, 1500);
      }
    });

    // ─── Init ───
    updateDisplay();
  })();
  </script>
</body>
</html>
